    up = down = 0

    # Count T shapes by whether their stem is above or below the bar.
    for r in range(h):
        for c in range(w - 2):
            if grid[r][c:c+3] == [2, 2, 2]:
                if r > 0 and grid[r-1][c+1] == 2:
                    up += 1
                if r + 1 < h and grid[r+1][c+1] == 2:
                    down += 1

    out = [[0] * 6 for _ in range(3)]
    up_slots = [(0, 0), (2, 0), (0, 2), (2, 2)]
    down_slots = [(0, 0), (2, 0), (0, 2), (2, 2)]
    for r, c in up_slots[:up]:
        out[r][c] = 3
    for r, c in down_slots[:down]:
        out[r][c + 3] = 1
    return out
